/**
 * Geographically Accurate India Telecom Network Map Data
 *
 * Source: Official Survey of India (SOI) boundary dataset.
 * Projection: Standard Web Mercator EPSG:3857, preserving accurate geographical
 * contours, aspect ratio (1.13), and exact coordinate alignment for all Indian cities.
 */

export const INDIA_MAP_BOUNDS = {
  viewWidth: 1000,
  viewHeight: 1150,
  minLon: 67.8,
  maxLon: 97.8,
  minLat: 6.5,
  maxLat: 37.5,
  padLeft: 45,
  padTop: 40,
  mapW: 910,
  mapH: 1031.1
};

const MIN_MX = (INDIA_MAP_BOUNDS.minLon * Math.PI) / 180;
const MAX_MX = (INDIA_MAP_BOUNDS.maxLon * Math.PI) / 180;
const MIN_MY = Math.log(Math.tan(Math.PI / 4 + (INDIA_MAP_BOUNDS.minLat * Math.PI) / 360));
const MAX_MY = Math.log(Math.tan(Math.PI / 4 + (INDIA_MAP_BOUNDS.maxLat * Math.PI) / 360));

/**
 * Mathematically exact Mercator projection from (lon, lat) to (x, y)
 * in the 1000x1150 map coordinate space.
 */
export const projectLonLat = (lon, lat) => {
  const mx = (lon * Math.PI) / 180;
  const my = Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
  const nx = (mx - MIN_MX) / (MAX_MX - MIN_MX);
  const ny = (MAX_MY - my) / (MAX_MY - MIN_MY);
  const px = INDIA_MAP_BOUNDS.padLeft + nx * INDIA_MAP_BOUNDS.mapW;
  const py = INDIA_MAP_BOUNDS.padTop + ny * INDIA_MAP_BOUNDS.mapH;
  return [Math.round(px * 10) / 10, Math.round(py * 10) / 10];
};

